package com.zdesk.companion;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.media.projection.*;
import android.net.Uri;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
public class MainActivity extends Activity {
 EditText server,code;CheckBox screen,mic,control,files;TextView status;Button start;java.io.File export;
 final Handler handler=new Handler(Looper.getMainLooper());
 public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff101b2b);ScrollView scroll=new ScrollView(this);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(32,36,32,36);layout.setBackgroundColor(0xff101b2b);scroll.addView(layout);setContentView(scroll);
  label(layout,"ZDesk",32);label(layout,"ANDROID COMPANION · 1.0",12);label(layout,"Connect your phone. Stay in control.",21);
  label(layout,"Server address",14);server=new EditText(this);server.setSingleLine();server.setText(getPreferences(0).getString("server","https://tydesk-broker.onrender.com"));layout.addView(server);
  label(layout,"Connection passcode or one-use code (blank to use saved pairing)",14);code=new EditText(this);code.setSingleLine();code.setInputType(129);layout.addView(code);
  screen=option(layout,"Share screen · Android approval required each session",true);mic=option(layout,"Share microphone / surrounding sound",false);control=option(layout,"Allow remote taps, swipes and text",false);files=option(layout,"Exchange selected files · up to 20 MB",false);
  label(layout,"Microphone sharing can transmit surrounding conversations. Start shares only the options you select. Changes apply on the next Start. Closing this setup screen leaves an active sharing notification; use Stop to end access.",14);
  button(layout,"Enable accessibility control",()->new AlertDialog.Builder(this).setTitle("Remote control permission").setMessage("Enable ZDesk remote control yourself in Android Accessibility settings only if you want the paired dashboard to tap, swipe and type during an active screen-sharing session. You can disable it at any time.").setPositiveButton("Open settings",(d,w)->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).setNegativeButton("Cancel",null).show());
  button(layout,"Select files to share",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,30);});
  start=button(layout,"Start sharing",this::begin);button(layout,"Stop sharing",()->{stopService(new Intent(this,ShareService.class));ShareService.allowControl=false;});
  button(layout,"Forget saved pairing",()->{stopService(new Intent(this,ShareService.class));Vault.forget(this);status.setText("Saved pairing removed. Revoke this device in the dashboard too.");});
  button(layout,"Save a received file",()->{java.io.File dir=new java.io.File(getExternalFilesDir(null),"Inbox");java.io.File[] incoming=dir.listFiles();if(incoming==null||incoming.length==0){status.setText("No received files yet.");return;}String[] names=new String[incoming.length];for(int j=0;j<names.length;j++)names[j]=incoming[j].getName();new AlertDialog.Builder(this).setTitle("Received files").setItems(names,(d,which)->{export=incoming[which];startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,export.getName()),31);}).show();});
  button(layout,"Open dashboard",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://tydesk-broker.onrender.com/"))));status=label(layout,"Ready · nothing is shared until Start and Android approval.",15);
 }
 TextView label(LinearLayout l,String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(0xffdcecf9);v.setPadding(0,12,0,14);l.addView(v);return v;}
 CheckBox option(LinearLayout l,String title,boolean checked){CheckBox c=new CheckBox(this);c.setText(title);c.setTextColor(0xffe9f6ff);c.setChecked(checked);l.addView(c);return c;}
 Button button(LinearLayout l,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());l.addView(b);return b;}
 protected void onResume(){super.onResume();handler.post(new Runnable(){public void run(){if(ShareService.active){screen.setChecked(ShareService.projectionActive);mic.setChecked(getSharedPreferences("options",0).getBoolean("mic",false));files.setChecked(getSharedPreferences("options",0).getBoolean("files",false));}screen.setEnabled(!ShareService.active);mic.setEnabled(!ShareService.active);files.setEnabled(!ShareService.active);control.setEnabled(!ShareService.active);if(status!=null)status.setText(getSharedPreferences("options",0).getString("status","Ready · nothing is shared until Start and Android approval."));handler.postDelayed(this,1500);}});}
 protected void onPause(){handler.removeCallbacksAndMessages(null);super.onPause();}
 void begin(){if(ShareService.active){status.setText("Already sharing. Stop the current session before starting another.");return;}if(control.isChecked()&&ControlService.current==null){status.setText("Enable ZDesk accessibility control first, or uncheck control for view-only sharing.");return;}try{new Api(server.getText().toString().trim(),null);}catch(Exception e){status.setText(e.getMessage());return;}if(!screen.isChecked()&&!mic.isChecked()&&!files.isChecked()){status.setText("Choose at least one sharing option.");return;}if(mic.isChecked()&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},20);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},21);return;}approveScreen();}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==20&&(results.length==0||results[0]!=PackageManager.PERMISSION_GRANTED)){status.setText("Microphone permission was not granted. Uncheck Microphone to continue without it.");return;}approveScreen();}
 void approveScreen(){if(screen.isChecked()){MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);Intent capture=Build.VERSION.SDK_INT>=34?m.createScreenCaptureIntent(MediaProjectionConfig.createConfigForDefaultDisplay()):m.createScreenCaptureIntent();startActivityForResult(capture,10);}else launch(0,null);}
 void launch(int result,Intent data){getPreferences(0).edit().putString("server",server.getText().toString().trim()).apply();getSharedPreferences("options",0).edit().putBoolean("control",control.isChecked()).putBoolean("files",files.isChecked()).putBoolean("mic",mic.isChecked()).apply();Intent service=new Intent(this,ShareService.class).putExtra("url",server.getText().toString().trim()).putExtra("code",code.getText().toString().trim()).putExtra("screen",screen.isChecked()).putExtra("mic",mic.isChecked()).putExtra("result",result).putExtra("data",data);code.setText("");startForegroundService(service);status.setText("Starting… See the persistent ZDesk notification for status and Stop.");}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null){if(request==10)status.setText("Screen permission cancelled. Nothing was started.");return;}if(request==10){launch(result,data);return;}if(request==30){JSONArray uris=new JSONArray();int count=data.getClipData()==null?1:data.getClipData().getItemCount();for(int i=0;i<Math.min(200,count);i++){Uri uri=data.getClipData()==null?data.getData():data.getClipData().getItemAt(i).getUri();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);uris.put(uri.toString());}catch(Exception ignored){}}getSharedPreferences("options",0).edit().putString("uris",uris.toString()).apply();status.setText(uris.length()+" files selected. Restart sharing if already connected.");}if(request==31&&export!=null){try(InputStream in=new FileInputStream(export);OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);status.setText("File saved.");}catch(Exception e){status.setText("Could not save file: "+e.getMessage());}}}
}
